 else: obs['method#'+p]=H(canon(x))'); [leaves(m[k],'/'+k) for k in ['revision','status','authority','claims','existing_requirements','new_requirements','common','comparison','coverage']]; leaves(m['tasks'][4],'/tasks/4'); pn={('protocol#L'+str(i)):H(s.encode()) for i,s in enumerate(Path('benchmark/protocol.md').read_text().splitlines(),1) if s.strip() and not s.startswith('#') and not s.startswith('|---')}; obs.update(pn); actual={x['id']:x['source']['value_sha256'] for x in b['source_obligations']}; print({'method_leaves':len(obs)-len(pn),'protocol_records':len(pn),'total':len(obs),'duplicate_records':len(b['source_obligations'])-len(actual),'source_value_mismatches':[k for k in set(obs)|set(actual) if obs.get(k)!=actual.get(k)]})"

